def document():
 d=Document();s=d.sections[0];s.top_margin=Cm(2);s.bottom_margin=Cm(2);s.left_margin=Cm(2.5);s.right_margin=Cm(1.5)
 n=d.styles['Normal'];n.font.name='Times New Roman';n.font.size=Pt(12);n.paragraph_format.space_after=Pt(6);n.paragraph_format.line_spacing=1.15
 for name in ['Heading 1','Heading 2','Heading 3']:
  d.styles[name].font.name='Times New Roman';d.styles[name].font.color.rgb=RGBColor.from_string('17365D')
 foot=s.footer.paragraphs[0];foot.alignment=2
 foot.add_run('Шагеева Р. Р. / ЛР-1  ·  ')
 field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');foot._p.append(field)
 return d

def para(d,text):d.add_paragraph(text)
def table(d,heads,records,widths=None):
 t=d.add_table(rows=1, cols=len(heads));t.style='Table Grid'
 for cell,text in zip(t.rows[0].cells,heads):
  cell.text=str(text);sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'E8EFF7');cell._tc.get_or_add_tcPr().append(sh)
 for row in records:
  for cell,text in zip(t.add_row().cells,row):cell.text='' if text is None else str(text)
 for row in t.rows:
  for cell in row.cells:
   for p in cell.paragraphs:
    p.paragraph_format.space_after=Pt(2)
    for r in p.runs:r.font.size=Pt(9)
 return t

def image(d,name,caption,width=16):
 p=ROOT/'screenshots'/name
 if not p.exists():raise FileNotFoundError(p)
 d.add_picture(str(p),width=Cm(width));p=d.add_paragraph(caption);p.alignment=1
 for r in p.runs:r.italic=True;r.font.size=Pt(10)

def code(d,text):
 p=d.add_paragraph()
 for line in textwrap.wrap(text,100,break_long_words=False,break_on_hyphens=False):
  r=p.add_run(line+'\n');r.font.name='Liberation Mono';r.font.size=Pt(8)
 p.paragraph_format.space_after=Pt(6)

